/* ============================================
   ERROR SUMMARY
   The Alert's error surface (status fill, status
   border, its radius and inset), holding a
   heading and a list of links, one per error.
   ============================================ */

/* Base */
.ds-error-summary {
  display: flex;
  align-items: flex-start;
  gap: var(--gap-200);
  box-sizing: border-box;
  width: 100%;
  padding: var(--padding-400);
  border: var(--border-025) solid var(--color-status-error-border);
  border-radius: var(--radius-200);
  background-color: var(--color-status-error-bg);
  color: var(--color-status-error-text);
}

.ds-error-summary:focus {
  outline: none;
}

.ds-error-summary:focus-visible {
  outline: var(--border-050) solid var(--color-action-primary-bg);
  outline-offset: var(--border-050);
}

.ds-error-summary__icon {
  flex-shrink: 0;
  --icon-size: var(--icon-size-600);
  line-height: 1;
  color: var(--color-status-error-border);
}

.ds-error-summary__content {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: var(--gap-100);
  min-width: 0;
}

.ds-error-summary__title {
  margin: 0;
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
}

.ds-error-summary__description {
  margin: 0;
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
}

/* List */
.ds-error-summary__list {
  display: flex;
  flex-direction: column;
  gap: var(--gap-100);
  margin: 0;
  padding: 0;
  list-style: none;
}

.ds-error-summary__link {
  border-radius: var(--radius-050);
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: inherit;
  text-decoration-line: underline;
  text-decoration-thickness: from-font;
  text-underline-offset: 0.2em;
}

.ds-error-summary__link:hover {
  text-decoration-thickness: var(--border-050);
}

.ds-error-summary__link:focus-visible {
  outline: var(--border-050) solid var(--color-action-primary-bg);
  outline-offset: var(--border-050);
}

'use client';

import React, { useEffect, useId, useRef } from 'react';
import { useLocale } from '../../behaviors/LocaleProvider';
import { formatNumber } from '../../behaviors/locale';
import type { ErrorSummaryError } from './fieldErrors';
import '../../fonts/material-symbols.css';
import './ErrorSummary.css';

/** Props owned by ErrorSummary itself; everything else falls through to the root `<section>`. */
type ErrorSummaryOwnProps = {
  /** The errors, in the form's order: each the id of the control it belongs to and what is wrong. The summary renders nothing while the list is empty. */
  errors: ErrorSummaryError<React.ReactNode>[];
  /** The heading, in place of the one `titleLabel` writes. Note: this replaces the native `title` attribute, which ErrorSummary does not expose. */
  title?: React.ReactNode;
  /** The heading for a given number of errors, already written in the locale. Defaults to "There is a problem" for one and "There are <count> problems" for more. */
  titleLabel?: (count: string, total: number) => string;
  /** A line under the heading, before the list. */
  description?: React.ReactNode;
  /** Move focus to the summary when the list goes from empty to holding errors (on a submit), so a screen reader reads it and a keyboard user starts from it. Defaults to true. */
  focusOnMount?: boolean;
  /** The heading's level, so the summary takes its place in the page's outline. Defaults to 2. */
  headingLevel?: 2 | 3 | 4;
  /** Called with a control's id after its link moves focus to it. */
  onErrorClick?: (id: string) => void;
  /** The BCP 47 locale the count is written in. Defaults to the nearest LocaleProvider's, else `en-US`. */
  locale?: string;
  /** Additional CSS classes. */
  className?: string;
};

export interface ErrorSummaryProps
  extends ErrorSummaryOwnProps,
    Omit<React.ComponentPropsWithRef<'section'>, keyof ErrorSummaryOwnProps | 'children'> {}

const DEFAULT_TITLE_LABEL = (count: string, total: number) =>
  total === 1 ? 'There is a problem' : `There are ${count} problems`;

/**
 * Every error on a form in one place, at the top of it: a heading that says
 * how many, and a link per error that moves focus to the control and scrolls
 * it into view. Takes the focus when errors first appear, so the reader
 * starts from what needs fixing.
 */
export function ErrorSummary({
  errors,
  title,
  titleLabel = DEFAULT_TITLE_LABEL,
  description,
  focusOnMount = true,
  headingLevel = 2,
  onErrorClick,
  locale: localeProp,
  className = '',
  ref,
  ...rest
}: ErrorSummaryProps) {
  const locale = useLocale(localeProp);
  const headingId = useId();
  const rootRef = useRef<HTMLElement | null>(null);
  const hadErrors = useRef(false);
  const count = errors.length;

  useEffect(() => {
    const has = count > 0;
    if (has && !hadErrors.current && focusOnMount) rootRef.current?.focus();
    hadErrors.current = has;
  }, [count, focusOnMount]);

  if (count === 0) return null;

  const setRef = (node: HTMLElement | null) => {
    rootRef.current = node;
    if (typeof ref === 'function') ref(node);
    else if (ref) ref.current = node;
  };

  /* Bring the control into view with its label above it, then focus it
     without a second scroll, so the reader sees the question as well as the
     box. The label is the field's own, when the control sits in one. */
  const goTo = (event: React.MouseEvent<HTMLAnchorElement>, id: string) => {
    const target = document.getElementById(id);
    if (!target) return;
    event.preventDefault();
    const frame = target.closest('.ds-field') ?? target;
    frame.scrollIntoView({ block: 'center' });
    target.focus({ preventScroll: true });
    onErrorClick?.(id);
  };

  const Heading = `h${headingLevel}` as const;
  const heading = title ?? titleLabel(formatNumber(count, locale), count);

  return (
    <section
      {...rest}
      ref={setRef}
      tabIndex={-1}
      aria-labelledby={headingId}
      className={['ds-error-summary', className].filter(Boolean).join(' ')}
    >
      <span className="ds-error-summary__icon material-symbols-rounded" aria-hidden="true">
        error
      </span>
      <div className="ds-error-summary__content">
        <Heading className="ds-error-summary__title" id={headingId}>
          {heading}
        </Heading>
        {description != null && description !== false && <p className="ds-error-summary__description">{description}</p>}
        <ul className="ds-error-summary__list">
          {errors.map((error, index) => (
            <li key={`${error.id}-${index}`} className="ds-error-summary__item">
              <a className="ds-error-summary__link" href={`#${error.id}`} onClick={(event) => goTo(event, error.id)}>
                {error.message}
              </a>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

// fieldErrorsFrom is a plain function beside the component, not a component,
// so the Fast Refresh rule that wants a component module to export only
// components does not apply to it.
// eslint-disable-next-line react-refresh/only-export-components
export { fieldErrorsFrom } from './fieldErrors';
export type { ErrorSummaryError, FieldErrors, FieldErrorsFromOptions } from './fieldErrors';

/**
 * Server field errors into the shapes ErrorSummary and Field take. No React,
 * so a route handler or a form action can call it too.
 */

/** One error ErrorSummary lists: the id of the control it belongs to, and what is wrong. */
export type ErrorSummaryError<Message = string> = {
  /** The id of the control the error belongs to; the summary's link focuses it. */
  id: string;
  /** What is wrong, in words that say how to fix it. */
  message: Message;
};

/** Options for {@link fieldErrorsFrom}. */
export type FieldErrorsFromOptions = {
  /** The control id for a field name, when the two differ (`email` named, `signup-email` its id). Defaults to the name itself. */
  idFor?: (name: string) => string;
  /** The order the summary lists fields in, usually the form's own order. Fields not named come after, in the record's order. */
  order?: readonly string[];
};

/** What {@link fieldErrorsFrom} returns: the summary's list, and one message per field for its `errorText`. */
export type FieldErrors = {
  /** Every message, one entry each, for ErrorSummary's `errors`. */
  errors: ErrorSummaryError[];
  /** One message per field name (several joined by a space), for each Field's or Input's `errorText`. */
  errorText: Record<string, string>;
};

/**
 * Turn the common server shape, `{ fieldName: message | message[] }`, into
 * ErrorSummary's `errors` and a per-field `errorText` map. Empty messages
 * and empty lists are dropped, so a record with nothing wrong gives empty
 * results.
 *
 * ```ts
 * const { errors, errorText } = fieldErrorsFrom(response.fieldErrors, { order: ['name', 'email'] });
 * ```
 */
export function fieldErrorsFrom(
  record: Readonly<Record<string, string | readonly string[] | null | undefined>> | null | undefined,
  options: FieldErrorsFromOptions = {},
): FieldErrors {
  const { idFor = (name) => name, order = [] } = options;
  const names = Object.keys(record ?? {});
  const ranked = [...order.filter((name) => names.includes(name)), ...names.filter((name) => !order.includes(name))];
  const errors: ErrorSummaryError[] = [];
  const errorText: Record<string, string> = {};
  for (const name of ranked) {
    const raw = record?.[name];
    const messages = (Array.isArray(raw) ? raw : [raw]).filter((m): m is string => typeof m === 'string' && m.trim() !== '');
    if (messages.length === 0) continue;
    const id = idFor(name);
    for (const message of messages) errors.push({ id, message });
    errorText[name] = messages.join(' ');
  }
  return { errors, errorText };
}
